<script setup lang="ts">import{ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from'@/shared/components/WareState.vue';import WarePhoneLink from'@/shared/components/WarePhoneLink.vue';import{agriDriverApi}from'../../api/agri-driver.api';const query=ref<any>({}),rows=ref<any[]>([]),loading=ref(true),error=ref('');async function load(){loading.value=true;error.value='';try{rows.value=await agriDriverApi.deliveryDetail(query.value)}catch(e){error.value=e instanceof Error?e.message:'送货明细加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}onLoad(q=>{query.value={date:String(q?.date||''),goodsId:Number(q?.goodsId),skuId:Number(q?.skuId),goodsName:decodeURIComponent(String(q?.goodsName||'')),skuName:decodeURIComponent(String(q?.skuName||'')),baseName:decodeURIComponent(String(q?.baseName||'')),supplierId:Number(q?.supplierId||0)};load()});onPullDownRefresh(load);</script>
<template><view class="page"><view class="hero"><b>{{query.goodsName}}</b><text>{{query.skuName||'默认规格'}} · {{query.date}} 场次</text><strong>合计 {{rows.reduce((s,x)=>s+x.purchaseCount,0)}} 件</strong></view><view class="head"><text>供应商</text><text>数量</text><text>状态</text></view><WareState v-if="loading" type="loading" title="正在加载供应商明细"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!rows.length" type="empty" title="暂无供应商送货明细"/><view v-for="x in rows" v-else :key="x.supplierId" class="row"><view><b>{{x.supplierName}}</b><WarePhoneLink v-if="x.phone" :phone="x.phone" compact/></view><strong>{{x.purchaseCount}} 件</strong><span>{{x.statusLabel}}</span></view></view></template>
<style scoped>.page{min-height:100vh;padding:18rpx 20rpx;background:var(--wms-background)}.hero{padding:18rpx;background:#fff}.hero b,.hero text,.hero strong{display:block}.hero b{font-size:26rpx}.hero text{margin-top:7rpx;color:var(--wms-text-secondary);font-size:18rpx}.hero strong{margin-top:13rpx;color:var(--wms-primary-700);font-size:22rpx}.head,.row{display:grid;grid-template-columns:minmax(0,1fr) 100rpx 100rpx;align-items:center;gap:8rpx}.head{margin-top:13rpx;padding:12rpx;background:var(--wms-primary-700);color:#fff;font-size:18rpx}.row{margin-top:5rpx;padding:13rpx;background:#fff;font-size:19rpx}.row strong{color:var(--wms-danger)}.row span{padding:4rpx 6rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:16rpx;text-align:center}</style>
